from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.gnb.oam.coam.classical.pages.navigatable_page import NavigatablePage
from taf.selenium.gnb.oam.coam.classical.pages.panels.view import ViewPanel


class Options(object):
    """
    The class corresponding to BTS status page on selenium_coam web, all operations under Options
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver):
        self._general = GeneralPage(driver)
        self._sessions_list = SessionListPage(driver)

    @property
    def general(self):
        return self._general

    @property
    def sessions_list(self):
        return self._sessions_list


class GeneralPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Options", "Settings", "General"]

    def __init__(self, driver):
        super(GeneralPage, self).__init__(driver)
        self._view_panel = GeneralPageViewPanel(driver)

    def get_lock_screen_time(self):
        return self._view_panel.get_lock_screen_time()

    def set_lock_screen_time(self, lock_time, enable_debug_log):
        self._view_panel.set_lock_screen_time(lock_time, enable_debug_log)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class GeneralPageViewPanel(ViewPanel):
    SCREEN_LOCK_INPUT_XPATH = '//*[contains(@class, "screen-lock-interval")]//input'
    ENABLE_DEBUG_LOG_XPATH = '//span[text()="Enable debug log"]'
    APPLY_BUTTON = '//ui-button[@a-text="Apply"]'

    def __init__(self, driver):
        super(GeneralPageViewPanel, self).__init__(driver)

    def get_lock_screen_time(self):
        self.wait_for_visibility_by_xpath(self.SCREEN_LOCK_INPUT_XPATH)
        return self.get_attribute_by_xpath(self.SCREEN_LOCK_INPUT_XPATH, 'value')

    def set_lock_screen_time(self, lock_time, enable_debug_log):
        self.insert_text_to_enable_element((By.XPATH, self.SCREEN_LOCK_INPUT_XPATH), lock_time)
        self.select_checkbox_by_specified_status(enable_debug_log,
                                                 self.ENABLE_DEBUG_LOG_XPATH,
                                                 self.ENABLE_DEBUG_LOG_XPATH)
        self.click_enabled_element((By.XPATH, self.APPLY_BUTTON))


class SessionListPage(NavigatablePage):
    _MENU_ROUTE_LIST = ["Options", "Sessions list"]

    def __init__(self, driver):
        super(SessionListPage, self).__init__(driver)
        self._view_panel = SessionListPageViewPanel(driver)

    def get_sessions_list_detail_info(self):
        return self._view_panel.get_sessions_list_detail_info()

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class SessionListPageViewPanel(ViewPanel):
    SESSION_TITLE_XPATH = '//div[contains(@class, "sessions-list-body")]//thead//th'
    SESSION_VALUE_XPATH = '//div[contains(@class, "sessions-list-body")]//tbody//tr'

    def __init__(self, driver):
        super(SessionListPageViewPanel, self).__init__(driver)

    def _get_session_title(self):
        """
        The returned value is like as below:
        ["ID", "Profile", "Secured connection", "Session type", "Read-only", "IP address", "Session ID"]
        """
        title_elems_xpath = self.get_elements_xpath_list(self.SESSION_TITLE_XPATH)
        return [self.get_attribute_by_xpath(title_xpath, 'title') for title_xpath in title_elems_xpath]

    def _get_session_value(self):
        """
        The returned value is like as below:
        [
            ["0", "Nemuadmin", "false", "EM", "false", "[::ffff:10.158.100.1]", "31"],
            ["1", "Nemuadmin", "true", "DXT", "false", "0.0.0.0",               "27"],
        ]
        """
        session_value_list = []

        for value_tr_xpath in self.get_elements_xpath_list(self.SESSION_VALUE_XPATH):
            values_tds_elem = self.driver.find_elements_by_xpath(value_tr_xpath + "//td")
            session_value_list.append([td_elem.text for td_elem in values_tds_elem])
        return session_value_list

    def get_sessions_list_detail_info(self):
        """
        The returned value is like as below:
        [
             {'ID': '0',
              'Profile': 'Nemuadmin',
              'Secured connection': 'false',
              'Session type': 'EM',
              'Read-only': 'false',
              'IP address': '[::ffff:10.158.100.1]',
              'Session ID': '31'},
             {'ID': '1',
              'Profile': 'Nemuadmin',
              'Secured connection': 'true',
              'Session type': 'DXT',
              'Read-only': 'false',
              'IP address': '0.0.0.0',
              'Session ID': '27'}
        ]
        """
        session_list_title = self._get_session_title()
        session_list_value = self._get_session_value()
        return [dict(zip(session_list_title, session_value)) for session_value in session_list_value]
